/// Binary search for a code point in the IDNA table.
pub fn lookupCodePoint(cp: u21) IdnaEntry {
    var lo: usize = 0;
    var hi: usize = idna_table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (idna_table[mid].range_end < cp) {
            lo = mid + 1;
        } else if (idna_table[mid].range_start > cp) {
            hi = mid;
        } else {
            return idna_table[mid];
        }
    }
    // Not found — treat as disallowed
    return .{ .range_start = cp, .range_end = cp, .status = .disallowed, .mapping_offset = 0, .mapping_len = 0 };
}

/// Get the mapping slice for an entry from the pool.
pub fn getMapping(entry: IdnaEntry) []const u21 {
    if (entry.mapping_len == 0) return &.{};
    return mapping_pool[entry.mapping_offset..][0..entry.mapping_len];
}

