/// Binary search for canonical decomposition of a code point.
pub fn getDecomposition(cp: u21) ?[]const u21 {
    var lo: usize = 0;
    var hi: usize = decomp_table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (decomp_table[mid].cp < cp) {
            lo = mid + 1;
        } else if (decomp_table[mid].cp > cp) {
            hi = mid;
        } else {
            const e = decomp_table[mid];
            return decomp_pool[e.offset..][0..e.len];
        }
    }
    return null;
}

