/// Get Canonical Combining Class for a code point (0 if not found).
pub fn getCcc(cp: u21) u8 {
    var lo: usize = 0;
    var hi: usize = ccc_table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (ccc_table[mid].cp < cp) {
            lo = mid + 1;
        } else if (ccc_table[mid].cp > cp) {
            hi = mid;
        } else {
            return ccc_table[mid].ccc;
        }
    }
    return 0;
}

/// Canonical composition pairs (965 pairs). Sorted by (first, second).
pub const CompPair = struct { first: u21, second: u21, composed: u21 };
