/// Look up a canonical composition pair.
pub fn getComposition(first: u21, second: u21) ?u21 {
    var lo: usize = 0;
    var hi: usize = comp_table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = comp_table[mid];
        if (e.first < first or (e.first == first and e.second < second)) {
            lo = mid + 1;
        } else if (e.first > first or (e.first == first and e.second > second)) {
            hi = mid;
        } else {
            return e.composed;
        }
    }
    return null;
}

// ── Tests ─────────────────────────────────────────────────────────

test "lookupCodePoint ASCII lowercase is valid" {
    const entry = lookupCodePoint('a');
    try std.testing.expect(entry.status == .valid);
}

test "lookupCodePoint ASCII uppercase is mapped" {
    const entry = lookupCodePoint('A');
    try std.testing.expect(entry.status == .mapped);
    const m = getMapping(entry);
    try std.testing.expectEqual(@as(u21, 'a'), m[0]);
}

test "lookupCodePoint fullwidth maps" {
    // U+FF21 FULLWIDTH LATIN CAPITAL LETTER A
    const entry = lookupCodePoint(0xFF21);
    try std.testing.expect(entry.status == .mapped);
}

test "lookupCodePoint U+0080 control is disallowed" {
    const entry = lookupCodePoint(0x0080);
    try std.testing.expect(entry.status == .disallowed);
}

test "getCcc for combining acute accent" {
    // U+0301 COMBINING ACUTE ACCENT has CCC=230
    try std.testing.expectEqual(@as(u8, 230), getCcc(0x0301));
}

test "getCcc for base character is 0" {
    try std.testing.expectEqual(@as(u8, 0), getCcc('a'));
}

test "getDecomposition e-acute" {
    // U+00E9 LATIN SMALL LETTER E WITH ACUTE → U+0065 U+0301
    const d = getDecomposition(0x00E9).?;
    try std.testing.expectEqual(@as(usize, 2), d.len);
    try std.testing.expectEqual(@as(u21, 0x0065), d[0]);
    try std.testing.expectEqual(@as(u21, 0x0301), d[1]);
}

test "getDecomposition ASCII returns null" {
    try std.testing.expect(getDecomposition('a') == null);
}

test "getComposition e + acute" {
    // U+0065 + U+0301 → U+00E9
    const c = getComposition(0x0065, 0x0301).?;
    try std.testing.expectEqual(@as(u21, 0x00E9), c);
}

test "getComposition nonexistent pair" {
    try std.testing.expect(getComposition('a', 'b') == null);
}

